<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';require dirname(__DIR__,2).'/app/autoload.php';
use FMonitor2\InstallationProcess\JobsSchemaMigration;use FMonitor2\Jobs\MariaDbJobQueue;
assertSameValue(true,class_exists(MariaDbJobQueue::class)&&class_exists(JobsSchemaMigration::class),'INTENTIONAL_RED: durable queue concurrency seam exists');
$host=getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1';$port=(int)(getenv('FMONITOR_TEST_DB_PORT')?:23306);$user=getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root';$password=getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local';$name='t_job_race_'.bin2hex(random_bytes(5));$admin=new mysqli($host,$user,$password,'',$port);$admin->query("CREATE DATABASE `{$name}` DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$db=new mysqli($host,$user,$password,$name,$port);$p='race_';$barrier=sys_get_temp_dir().'/fm2-job-race-'.bin2hex(random_bytes(6));mkdir($barrier,0700);$children=[];
try{JobsSchemaMigration::apply($db,$p);$queue=new MariaDbJobQueue($db,$p,static fn():string=>'2026-09-09T10:00:00.000000Z',static fn():string=>str_repeat('a',64),['test.echo'=>[1]]);$job=$queue->enqueue(['jobType'=>'test.echo','payloadVersion'=>1,'payload'=>['value'=>'race'],'availableAtUtc'=>'2026-09-09T10:00:00.000000Z','idempotencyKey'=>'99999999-9999-4999-8999-999999999999','actor'=>['type'=>'system','id'=>'race']]);
    $db->begin_transaction();$db->query("SELECT job_id FROM `{$p}fm2_jobs` WHERE job_id=".(int)$job['jobId'].' FOR UPDATE');
    foreach([1,2]as$i){$arrival="$barrier/arrival-$i";$cmd=[PHP_BINARY,dirname(__DIR__).'/Support/jobs_claim_worker.php',$name,$p,"worker-$i",$arrival,"$barrier/release",str_repeat((string)$i,64)];$process=proc_open($cmd,[0=>['file','/dev/null','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,dirname(__DIR__,2),array_replace(getenv(),['FMONITOR_TEST_DB_ADMIN_PASSWORD'=>$password]));if(!is_resource($process))throw new TestFailure('SETUP_FAILURE claim worker');$children[]=[$process,$pipes,$arrival];}
    $deadline=microtime(true)+5;while((!is_file($children[0][2])||!is_file($children[1][2]))&&microtime(true)<$deadline)usleep(1000);assertSameValue(true,is_file($children[0][2])&&is_file($children[1][2]),'both connected claim workers reach pre-claim barrier');foreach($children as[$process])assertSameValue(true,proc_get_status($process)['running'],'both claim workers remain live while parent holds row lock');file_put_contents("$barrier/release","go\n",LOCK_EX);usleep(100000);foreach($children as[$process])assertSameValue(true,proc_get_status($process)['running'],'both claims are causally blocked by held ready row');$db->commit();$buffers=array_fill(0,count($children),['out'=>'','err'=>'','exit'=>null]);foreach($children as[, $pipes])foreach([1,2]as$fd)stream_set_blocking($pipes[$fd],false);$deadline=microtime(true)+10;do{$running=false;foreach($children as$i=>[$process,$pipes]){$buffers[$i]['out'].=stream_get_contents($pipes[1]);$buffers[$i]['err'].=stream_get_contents($pipes[2]);$status=proc_get_status($process);if($status['running'])$running=true;elseif($buffers[$i]['exit']===null)$buffers[$i]['exit']=$status['exitcode'];}if(!$running)break;if(microtime(true)>=$deadline){foreach($children as[$process])if(proc_get_status($process)['running'])proc_terminate($process,9);throw new TestFailure('SETUP_FAILURE bounded claim children timeout');}usleep(10000);}while(true);$results=[];foreach($children as$i=>[$process,$pipes]){$buffers[$i]['out'].=stream_get_contents($pipes[1]);$buffers[$i]['err'].=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$closed=proc_close($process);$exit=$buffers[$i]['exit']??$closed;assertSameValue([0,''],[$exit,$buffers[$i]['err']],'bounded claim child');$results[]=json_decode(trim($buffers[$i]['out']),true,512,JSON_THROW_ON_ERROR);}$counts=array_map('count',$results);$sorted=$counts;sort($sorted);assertSameValue([0,1],$sorted,'two simultaneous claims return the one job exactly once');$winner=$results[array_search(1,$counts,true)][0];assertSameValue((int)$job['jobId'],(int)$winner['jobId'],'winner owns exact queued job');assertSameValue(1,(int)$db->query("SELECT COUNT(*)n FROM `{$p}fm2_job_events` WHERE job_id=".(int)$job['jobId']." AND event_type='claimed'")->fetch_assoc()['n'],'race persists one claim event');echo"PASS: DURABLE-BACKGROUND-JOBS-001 bounded MariaDB claim race\n";
}finally{foreach($children as[$process,$pipes])if(is_resource($process)){proc_terminate($process,9);proc_close($process);}foreach(glob("$barrier/*")?:[]as$file)unlink($file);rmdir($barrier);$db->close();$admin->query("DROP DATABASE IF EXISTS `{$name}`");$admin->close();}
